// Literal port of the team's Casa3DSDK (module interaction/collision). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installInteractionCollision(K: Kernel, shared: Shared): void {
  // ---------- collision with objects (first person) ----------
  const NO_COLLIDE = /(^|_)(rug|floor|concrete|dirt|lawn|deck|ceiling_light|pendant|chandelier|spot|picture|curtain|blinds|wall_shelving|plank_shelf|wall_ac|ac_condenser|pool|soaking_tub|pergola|stairs|mirror)/;
  function registerCollision(m, M) {
    const h = m.h || 0, y = M.y || 0;
    if (NO_COLLIDE.test(m.type) || m.category === 'ground_cover' || h < 0.3 || y >= 0.9 || !(m.w > 0.05) || !(m.d > 0.05)) return;
    let w = m.w, d = m.d; if (/tree|palm_tree/.test(m.type)) { w = Math.min(w, 0.5); d = Math.min(d, 0.5); }
    shared.inter.objs.push({ f: M.floor, cx: m.x, cz: m.z, c: Math.cos(M.ry), s: Math.sin(M.ry), hw: w / 2, hd: d / 2, type: m.type });
  }
  function objectDistance(o, x, z) { // signed distance to the rectangle (negative inside)
    const dx = x - o.cx, dz = z - o.cz, lx = dx * o.c - dz * o.s, lz = dx * o.s + dz * o.c, ex = Math.abs(lx) - o.hw, ez = Math.abs(lz) - o.hd;
    return ex > 0 || ez > 0 ? Math.hypot(Math.max(ex, 0), Math.max(ez, 0)) : Math.max(ex, ez);
  }
  function collideObject(x, z, fx, fz, floor) { // blocks entering or going deeper into an object; whoever is already inside (when clicking the room) can leave
    const R = 0.2;
    for (const o of shared.inter.objs) { if (o.f !== -1 ? o.f !== floor : floor !== 0) continue; const d1 = objectDistance(o, x, z); if (d1 < R && d1 < objectDistance(o, fx, fz) - 1e-6) return true; }
    return false;
  }
  // collision of whoever walks (radius opt.radius, default 0.24): walls, closed doors, lot walls, gates and furniture. opt.from = [x, z] of where they came from (whoever is already inside a piece of furniture can leave).
  // The game may ignore this and use its own grid: the same volumes are in colliders (aabb / obb) and the open/closed state arrives through cfg.onCollider.
  function collideAt(x, z, floor, opt) {
    opt = opt || {}; const R = opt.radius != null ? opt.radius : 0.24;
    for (const c of shared.ctx.colliders) {
      if (c.off) continue;
      if (c.f !== -1 && c.f !== floor) continue; if (c.f === -1 && floor !== 0) continue;
      const nx = Math.max(c.x0, Math.min(x, c.x1)), nz = Math.max(c.z0, Math.min(z, c.z1));
      if ((x - nx) ** 2 + (z - nz) ** 2 < R * R) return true;
    }
    const de = opt.from || [x + 1e4, z + 1e4];
    return collideObject(x, z, de[0], de[1], floor);
  }
  Object.assign(K, { NO_COLLIDE, registerCollision, objectDistance, collideObject, collideAt });
}
